10:     const lines = content.split('\n');
11:     const tasks = [];
12:     const urlRegex = /(https?:\/\/[^\s\)]+)/g;
13: 
14:     lines.forEach(line => {
15:       const match = line.match(urlRegex);
16:       if (match) {
17:         const titleMatch = line.match(/\[([^\]]+)\]/);
18:         tasks.push({
19:           url: match[0],
20:           title: titleMatch ? titleMatch[1] : 'Untitled Web Serial',
21:           status: 'pending',
22:           rawLine: line.trim()
23:         });
24:       }
25:     });
26:     return tasks;
27:   }
