29:   // Scans file nodes to find asset-less entries (missing content/cover/epub)
30:   auditLibraryVault(fileEntries) {
31:     return fileEntries.filter(entry => {
32:       const isBook = entry.path.endsWith('.md') && !entry.path.endsWith('links.md');
33:       if (!isBook) return false;
34: 
35:       const hasContent = entry.content && entry.content.length > 300;
36:       const hasCover = /cover:\s*['"][^'"]+['"]/i.test(entry.content || '');
37:       const hasChapters = /##\s+Chapter/i.test(entry.content || '');
38:       const isAcquisitionStub = (entry.content || '').includes(this.acquisitionTag);
39: 
40:       // Flagged as asset-less if missing content body or explicit chapters
41:       return !hasContent || !hasCover || !hasChapters || isAcquisitionStub;
42:     }).map(entry => ({
43:       ...entry,
44:       isStub: (entry.content || '').includes(this.acquisitionTag),
45:       missingCover: !/cover:\s*['"][^'"]+['"]/i.test(entry.content || ''),
46:       missingChapters: !/##\s+Chapter/i.test(entry.content || '')
